#!/usr/bin/env python3
import subprocess,pathlib,json,hashlib,datetime
out=pathlib.Path('docs/review/evidence/config-acceptance/runtime'); inventory=json.loads((out/'inventory-fragment.json').read_text())
commands=[('config-reader-search.log',['rg','-n',r'config\.|config\[|context\.config|contract\.config|invocation\.configuration|targetsFrom|resolveTestProviderConfiguration|resolveReferencedValue','skills/nova','skills/common/plugin-runtime','skills/common/plugins','skills/buster/plugins','skills/buster/engine/test-gates','--glob','!**/tests/**','--glob','!**/dist/**','--glob','!**/node_modules/**']),('module-reader-search.log',['rg','-n',r'writeRunSnapshots|verifyPinnedGraph|verifyPinnedPackages|moduleStages|cumulativeStages|attempt.created|attempt.dispatched|stage.started|repairBudget|maxTechnicalRetries|CURRENT_RUNTIME_DISPATCH_PROFILE|CURRENT_REVIEW_CACHE_PROFILE','skills/nova','skills/common/plugin-runtime/sdk','--glob','!**/tests/**','--glob','!**/dist/**']),('env-cli-search.log',['rg','-n',r'process\.env|process\.argv|--platform|--pipeline|--project|--recover','skills/nova','skills/common/plugins','skills/buster/plugins','--glob','!**/tests/**','--glob','!**/dist/**']),('identity.log',['git','rev-parse','HEAD','HEAD^{tree}']),('node-version.log',['node','--version']),('python-version.log',['python3','--version'])]
records=[]
for file,cmd in commands:
 p=subprocess.run(cmd,text=True,capture_output=True);(out/file).write_text(p.stdout+p.stderr); records.append({'command':cmd,'exitCode':p.returncode,'rawEvidence':str(out/file),'sha256':hashlib.sha256((out/file).read_bytes()).hexdigest(),'observedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'source discovery only; not productive implementation acceptance'})
(out/'semantic-commands.json').write_text(json.dumps(records,indent=2)+'\n')
paths=sorted({r['source']['path'] for r in inventory['rows'] if r.get('semanticStatus','').startswith('source-traced')}|{'skills/common/plugin-runtime/foundation/registry/schema.ts','skills/common/plugin-runtime/foundation/registry/configuration.ts','skills/nova/core/execution/engine-snapshots.ts','skills/nova/core/execution/engine-run.ts','skills/nova/core/execution/engine-runtime.ts','skills/nova/core/execution/stage-executor.ts','skills/nova/core/execution/adapter-startup.ts','skills/nova/core/execution/pipeline-loop.ts','skills/nova/core/telemetry/observers.ts','skills/nova/project/recovery.ts','skills/nova/project/compiler.ts','skills/nova/project/coverage.ts','skills/common/plugins/runtime-dispatch/src/openclaw-config.ts','skills/common/plugins/runtime-dispatch/src/openclaw.ts'})
(out/'consumer-excerpts.json').write_text(json.dumps([{'path':p,'sha256':hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest(),'lines':[{'line':i,'text':l} for i,l in enumerate(pathlib.Path(p).read_text().splitlines(),1)]} for p in paths],indent=2)+'\n')
ids=[r['id'] for r in inventory['rows']]; stale=[s['path'] for s in inventory['sources'] if hashlib.sha256(pathlib.Path(s['path']).read_bytes()).hexdigest()!=s['sha256']]
check={'id':'RT-C0-SCHEMA-DISCOVERY','actualCommands':records,'sourceIdentity':inventory['identity'],'observed':{'plugins':len(json.loads((out/'plugin-roster.json').read_text())),'distinctSchemas':len({x['path'] for x in json.loads((out/'schema-roster.json').read_text())}),'rows':len(ids),'duplicateIds':len(ids)-len(set(ids)),'staleSources':stale,'schemaRefGaps':[g for g in inventory['gaps'] if 'REF' in g['id']]},'result':'passed' if len(ids)==len(set(ids)) and not stale else 'failed','reason':'Only scanner extraction identity/ID/local-ref consistency observed. Does NOT pass C0 semantic or productive-effect acceptance.','reviewerConfirmation':'pending'}
(out/'source-verification.json').write_text(json.dumps(check,indent=2)+'\n');print(json.dumps(check['observed']))
